				Property: "foo",
				Operator: "?",
				Value:    "bar",
			},
			wantErr: true,
		},
		{
			name: "valid",
			constraint: constraint{
				Property: "foo",
				Operator: "eq",
				Value:    "bar",
			},
		},
	}

	for _, tt := range tests {
		var (
			constraint = tt.constraint
			wantErr    = tt.wantErr
